"""Original hyperglycemic-emergency chapter: adult DKA."""
from qbank_authoring import question,ref,finalize
CR=ref('International Consensus: Hyperglycemic Crises in Adults With Diabetes, 2024','https://doi.org/10.2337/dci24-0032')
GL=ref('ADA Standards—2026: Glycemic Goals, Hypoglycemia and Hyperglycemic Crises','https://doi.org/10.2337/dc26-s006')
HY=ref('Endocrine Society: Evaluation and Management of Adult Hypoglycemic Disorders','https://academic.oup.com/jcem/article/94/3/709/2596247')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which combination meets the 2024 adult consensus definition of DKA?', 'Diabetes or glucose at least 200 mg/dL, significant ketosis and metabolic acidosis',[
 ('Glucose above 250 mg/dL alone','Hyperglycemia without ketosis and acidosis does not establish DKA.'),('Any positive urine ketone result without acidosis','Fasting and other states can produce ketones without DKA.'),('Hyperosmolality above 320 without ketonemia or acidosis','That describes a different hyperglycemic-emergency pathway.')],
 'DKA requires three components', '**The glucose/history criterion, ketosis and acidosis must all be assessed.**',['Significant ketosis is beta-hydroxybutyrate at least 3 mmol/L or an appropriate urine alternative.','Acidosis is pH below 7.3 or bicarbonate below 18 mmol/L.'], '**Do not use an old glucose threshold to exclude an insulin-deficient crisis.**',['Known diabetes can satisfy the diabetes component even with lower glucose.','Assess triggers and severity concurrently.'],[['D','Diabetes or glucose at least 200'],['K','Significant ketosis'],['A','Metabolic acidosis']],[CR])
q('An insulin-treated patient has glucose 188 mg/dL, beta-hydroxybutyrate 5 mmol/L and venous pH 7.20 after prolonged vomiting. Which diagnosis is most appropriate?', 'DKA can be present despite the glucose being below 200 mg/dL',[
 ('DKA is excluded in all patients below 250 mg/dL','Known diabetes plus significant ketosis and acidosis can meet the revised framework.'),('HHS is the best fit for glucose 188','HHS requires marked hyperglycemia and hyperosmolality.'),('The ketone value is too low to support DKA','Five mmol/L exceeds the significant-ketonemia threshold.')],
 'Clinical insulin deficiency can occur without marked hyperglycemia', '**Reduced intake, SGLT2 therapy and prior insulin can lower the glucose at presentation.**',['Known diabetes meets the diabetes/history component.','Alternative or additional causes of acidosis still need assessment.'], '**Treat the ketotic acidosis rather than waiting for glucose to rise.**',['Dextrose may be needed early to permit continued insulin.','Use the monitored adult DKA pathway.'],[['Glucose','Can be relatively low'],['Ketones','Clearly elevated'],['Acidosis','Requires active treatment']],[CR],'clinical_scenario')
q('Which variable is preferred for directly monitoring ketonemia during DKA treatment?', 'Blood beta-hydroxybutyrate',[
 ('Urine ketone darkness alone','Urine ketones lag and can become more positive as beta-hydroxybutyrate converts to acetoacetate.'),('A1C every hour','It reflects chronic exposure rather than acute ketone clearance.'),('Urine glucose concentration alone','This does not quantify ketoacidosis resolution.')],
 'Measure the dominant ketone rather than a delayed surrogate', '**Beta-hydroxybutyrate directly tracks the major circulating ketone in DKA.**',['Urine nitroprusside tests do not adequately measure it.','Glucose can normalize before ketones clear.'], '**Continue treatment until metabolic resolution.**',['Use serial pH or bicarbonate along with ketones.','Do not stop insulin solely because the urine strip remains positive or glucose is lower.'],[['Preferred ketone','Beta-hydroxybutyrate'],['Urine limitation','Lag and changing ketone proportions'],['Resolution','Metabolic criteria']],[CR])
q('Why can serum potassium be normal or high at presentation despite a large total-body potassium deficit in DKA?', 'Insulin deficiency and hypertonicity shift potassium extracellularly while osmotic diuresis causes body losses',[
 ('A high concentration proves excess total-body potassium in every DKA case','Concentration and total stores differ.'),('The kidney completely conserves potassium throughout osmotic diuresis','Substantial urinary losses occur.'),('Insulin treatment usually drives potassium out of cells','It promotes intracellular uptake.')],
 'A concentration can conceal depleted stores', '**Insulin and fluid treatment can rapidly reveal the deficit.**',['Urinary and gastrointestinal losses contribute.','Kidney impairment modifies both losses and replacement safety.'], '**Monitor and replace potassium according to serial values and renal function.**',['Do not rely on the admission value alone.','Severe hypokalemia creates arrhythmic and respiratory risk.'],[['Before treatment','Extracellular shift can mask deficit'],['During treatment','Potassium may fall rapidly'],['Safety','Serial potassium and kidney assessment']],[CR])
q('An adult with DKA has potassium 3.1 mmol/L. What is the appropriate initial insulin principle under the 2024 consensus?', 'Replace potassium and defer insulin until potassium is above 3.5 mmol/L',[
 ('Start full-dose insulin immediately without potassium','This can worsen dangerous hypokalemia.'),('Avoid potassium because all DKA patients have excess stores','Total-body depletion is common.'),('Delay all fluids and supportive care until potassium is normal','Other resuscitation should continue as appropriate.')],
 'Very low potassium changes the sequence of therapy', '**Insulin shifts potassium into cells and can provoke arrhythmia or weakness.**',['The updated adult threshold is above 3.5 mmol/L before insulin begins.','Replacement rate and route require a monitored protocol and renal assessment.'], '**Recheck frequently while correcting the deficit.**',['Continue appropriate fluid and trigger management.','Do not confuse this threshold with older 3.3 mmol/L teaching.'],[['Admission potassium','3.1 mmol/L'],['Immediate issue','Replace safely'],['Insulin start','After potassium exceeds 3.5']],[CR],'clinical_scenario')
q('For an adult with DKA and no cardiac or renal compromise, which initial fluid approach is consistent with the 2024 consensus?', 'Isotonic saline or a balanced crystalloid, typically 500–1,000 mL/hour during the first 2–4 hours with reassessment',[
 ('A fixed large volume without clinical reassessment for every patient','Fluid needs vary with perfusion, age and comorbidity.'),('Hypotonic dextrose as the sole initial resuscitation fluid in all cases','Initial restoration generally uses isotonic fluid.'),('No fluid until glucose normalizes','Volume resuscitation is a major early treatment component.')],
 'Restore perfusion while anticipating electrolyte shifts', '**Volume replacement improves renal perfusion and reduces counterregulatory drive.**',['Balanced fluids may reduce hyperchloremic acidosis.','Subsequent fluid choice follows sodium, osmolality and clinical balance.'], '**Use smaller boluses in vulnerable patients.**',['Heart failure, older age and dialysis require cautious individualized administration.','Monitor respiratory status and urine output.'],[['Typical initial adult rate','500–1,000 mL/hour'],['Suitable fluid','Isotonic saline or balanced crystalloid'],['Caution','Cardiac/renal compromise']],[CR])
q('A frail dialysis patient presents with DKA and pulmonary congestion. What is the safest fluid principle?', 'Use small, reassessed boluses only when indicated and individualize fluid replacement with the renal team',[
 ('Give the full standard estimated deficit automatically','Osmotic urinary losses may be limited and overload risk is high.'),('All DKA patients must receive identical hourly volumes','Comorbidity substantially changes fluid requirements.'),('DKA cannot occur in dialysis patients','Insulin deficiency can still produce ketoacidosis.')],
 'The usual volume-deficit model can fail in anuria', '**Dialysis dependence changes potassium and fluid handling.**',['Congestion and shock must be distinguished.','Insulin clearance and hypoglycemia risk also differ.'], '**Use integrated bedside volume and metabolic assessment.**',['Small boluses such as 250 mL may be used when needed under guidance.','Arrange dialysis for appropriate refractory complications rather than as a replacement for insulin.'],[['Anuria','Different fluid-loss pattern'],['Congestion','High overload risk'],['Prescription','Individualized and frequently reassessed']],[CR],'clinical_scenario')
q('Which insulin regimen is usual for significant adult DKA once potassium permits treatment?', 'Fixed-rate IV short-acting insulin, commonly 0.1 units/kg/hour initially',[
 ('A single long-acting injection as the only acute treatment in every severe case','Severe DKA needs closely titratable monitored treatment.'),('Correction-only insulin once daily','This does not provide continuous suppression of ketogenesis.'),('Withhold insulin after the first fall in glucose despite ongoing ketosis','Ketone clearance still requires insulin.')],
 'Insulin must suppress ketogenesis continuously', '**IV insulin permits frequent adjustment during an acute crisis.**',['The dose changes as glucose falls.','Subcutaneous rapid analog protocols can suit selected uncomplicated mild or moderate cases.'], '**Match the care setting to severity and monitoring capacity.**',['Severe disease, shock or HHS is not the routine subcutaneous pathway.','Check glucose frequently and electrolytes on schedule.'],[['Usual significant DKA','IV short-acting insulin'],['Initial common rate','0.1 units/kg/hour'],['Selected mild disease','Protocolized SC option']],[CR])
q('During DKA treatment, glucose falls to 220 mg/dL but beta-hydroxybutyrate remains 3.5 mmol/L. What is the best next principle?', 'Add dextrose-containing fluid and continue insulin at an adjusted rate until ketoacidosis resolves',[
 ('Stop insulin because glucose is below 250','Glucose correction can precede ketone clearance.'),('Give additional insulin without monitoring or any glucose support','This risks hypoglycemia.'),('Switch to a urine-glucose-only endpoint','Urine glucose does not establish metabolic resolution.')],
 'Separate glucose normalization from ketoacidosis resolution', '**Dextrose allows ongoing insulin to suppress ketogenesis without driving glucose too low.**',['The consensus commonly reduces IV insulin to about 0.05 units/kg/hour after glucose falls below 250.','The exact infusion and glucose plan follows the monitored protocol.'], '**Continue ketone and acid-base reassessment.**',['Do not use glucose alone as the stopping criterion.','Assess ongoing trigger control.'],[['Glucose below 250','Add dextrose and adjust insulin'],['Ketones remain high','Continue metabolic treatment'],['Endpoint','Ketone and pH/bicarbonate resolution']],[CR],'clinical_scenario')
q('Which findings meet the 2024 DKA resolution criteria?', 'Plasma ketones below 0.6 mmol/L plus venous pH at least 7.3 or bicarbonate at least 18 mmol/L',[
 ('Glucose below 250 alone','This does not establish ketone clearance.'),('A persistently positive urine strip alone means DKA cannot have resolved','Urine ketones can lag and change during recovery.'),('Anion gap closure is the only accepted endpoint regardless of ketones','Hyperchloremia can confound acid-base recovery and the gap is not the preferred sole criterion.')],
 'Use direct metabolic endpoints', '**Ketone clearance is combined with pH or bicarbonate recovery.**',['Glucose should ideally also be below 200 mg/dL.','A normal-gap acidosis can persist after chloride-rich fluids.'], '**Plan a safe transition rather than abruptly ending coverage.**',['Ensure a subcutaneous regimen and nutrition plan.','Continue evaluation of the precipitating cause.'],[['Ketones','Below 0.6 mmol/L'],['Acid-base','pH at least 7.3 or bicarbonate at least 18'],['Glucose','Ideally below 200']],[CR])
q('Ketones have cleared after DKA treatment, but bicarbonate remains mildly low with high chloride and a normal gap. What is the most likely explanation?', 'Recovery-phase hyperchloremic metabolic acidosis',[
 ('Persistent severe ketoacidosis is proven despite cleared ketones','The chloride and ketone pattern suggests another mechanism.'),('A low bicarbonate is always an assay artifact','A genuine normal-gap acidosis can persist.'),('The patient must receive indefinite high-dose insulin solely for hyperchloremia','Insulin need should follow metabolic and diabetes assessment, not chloride alone.')],
 'Treatment and urinary losses can change the type of acidosis', '**Chloride-rich fluid and loss of ketoanions can contribute to a normal-gap phase.**',['This is often self-limited.','Direct ketone measurement helps avoid misclassifying ongoing DKA.'], '**Use the full resolution criteria and clinical state.**',['Assess other causes if the course is atypical.','Avoid using the anion gap as the only endpoint.'],[['Ketones','Cleared'],['Chloride','Elevated'],['Residual process','Normal-gap acidosis']],[CR],'clinical_scenario')
q('When should bicarbonate be considered in adult DKA according to the 2024 consensus?', 'Selected severe acidemia, generally pH below 7.0',[
 ('Routine use in every patient with pH below 7.3','Routine bicarbonate is not recommended.'),('Whenever urine ketones remain positive despite normal pH','Urine positivity alone is not an indication.'),('As a substitute for insulin and fluid treatment','It does not stop ketone production.')],
 'Routine alkali has not shown benefit in ordinary DKA', '**Potential harms include hypokalemia and adverse oxygen-delivery effects.**',['Severe acidemia can impair cardiovascular function and justifies selected consideration.','Treatment requires a monitored protocol.'], '**Correct the primary ketotic mechanism.**',['Follow potassium especially closely if bicarbonate is used.','Do not extrapolate a severe-pH exception to all DKA.'],[['Routine DKA','No routine bicarbonate'],['Selected threshold','pH below 7.0'],['Core treatment','Insulin, fluids and electrolytes']],[CR])
q('Which statement about phosphate during DKA treatment is correct?', 'Routine replacement is unnecessary, but significant depletion with muscle weakness or cardiopulmonary compromise can justify treatment',[
 ('Every patient requires aggressive IV phosphate regardless of level','Routine replacement has not improved outcomes and can cause harm.'),('Phosphate never falls during insulin therapy','Intracellular shifts and prior losses can lower it.'),('IV phosphate carries no calcium-related risk','Overreplacement can cause hypocalcemia.')],
 'A biochemical fall is not an automatic infusion indication', '**Insulin shifts phosphate intracellularly and can reveal depleted stores.**',['The 2024 consensus highlights weakness or cardiopulmonary compromise with phosphate below 1 mmol/L.','The clinical context matters more than a single isolated mild fall.'], '**Use monitored replacement when indicated.**',['Account for potassium in phosphate preparations.','Check calcium, phosphate and kidney function.'],[['Routine replacement','Not recommended'],['Selected use','Symptomatic significant depletion'],['Hazard','Hypocalcemia and overreplacement']],[CR])
q('Which patient is a reasonable candidate for a validated subcutaneous rapid-acting insulin protocol rather than IV insulin?', 'A stable adult with uncomplicated mild DKA and reliable frequent nursing assessment',[
 ('A patient in shock with severe DKA','Severe instability calls for IV monitored treatment.'),('A patient with HHS and altered consciousness','This is not the routine mild-DKA subcutaneous pathway.'),('Any patient if only once-daily observation is available','Frequent dosing and monitoring are essential.')],
 'Route selection depends on severity and care capability', '**Selected mild or moderate DKA can be managed with rapid analog injections every one to two hours under protocol.**',['This does not mean ordinary once-daily correction treatment.','Severe disease and HHS require a different approach.'], '**Confirm access to serial glucose, electrolyte and clinical checks.**',['Escalate if response or stability worsens.','Treat the precipitant and plan transition.'],[['Candidate','Uncomplicated stable mild disease'],['Requirement','Frequent protocolized care'],['Exclusion','Severe instability or HHS']],[CR])
q('Which precipitant must be actively sought in recurrent DKA even when no infection is found?', 'Interrupted insulin access or delivery, including practical and psychosocial barriers',[
 ('All recurrent episodes prove intentional behavior','Cost, equipment failure, distress and illness can contribute.'),('A normal temperature excludes every serious precipitant','Infarction and other causes can be afebrile.'),('No evaluation is needed if DKA occurred before','Each episode can have a new trigger.')],
 'Prevent recurrence by finding the actual barrier', '**Insulin omission or delivery failure is a major precipitating mechanism.**',['Food insecurity, cost and fear of hypoglycemia may contribute.','Infection, ischemia and drugs remain important alternatives.'], '**Create a workable discharge and support plan.**',['Check supply access, sick-day skills and device backup.','Use a nonjudgmental assessment of distress and mental health.'],[['Potential cause','Access or delivery interruption'],['Assessment','Practical and psychosocial factors'],['Prevention','Supplies, education and follow-up']],[CR,GL])
q('Before stopping IV insulin after DKA resolution, what transition step reduces rebound hyperglycemia and ketosis?', 'Provide an appropriate subcutaneous basal regimen with about one to two hours of overlap',[
 ('Stop IV insulin and wait until the next day for basal coverage','This creates an insulin gap.'),('Use only a bedtime glucose check with no insulin plan','Monitoring does not replace physiological coverage.'),('Continue the same fixed infusion indefinitely regardless of recovery','A planned safe transition is preferable.')],
 'Avoid a gap between short-acting IV delivery and subcutaneous action', '**The 2024 consensus recommends one to two hours of overlap.**',['Dose choice reflects prior regimen, current needs, kidney function and intake.','Existing basal insulin may already provide part of the coverage.'], '**Confirm that the regimen is practical after discharge.**',['Reconcile supplies and education.','Do not copy an ineffective preadmission regimen without reviewing the trigger.'],[['IV insulin','Very short residual action'],['Subcutaneous basal','Needs onset time'],['Overlap','About one to two hours']],[CR])
q('Vomiting-associated alkalosis coexists with substantial ketonemia in a patient with diabetes. What is the key diagnostic caution?', 'An alkalinizing process can partly mask the pH and bicarbonate effects of ketoacid accumulation',[
 ('Vomiting excludes ketoacidosis','The processes can coexist.'),('A high pH proves that ketones are clinically irrelevant','A mixed disorder can conceal a serious acid load.'),('Only the glucose value is needed','Ketones, acid-base components and context are all necessary.')],
 'Mixed disorders are common in hyperglycemic crises', '**Gastric acid loss and volume contraction can create metabolic alkalosis.**',['Lactic acidosis and respiratory processes can also coexist.','The gap and direct ketones help reveal the metabolic burden.'], '**Assess the complete picture rather than one normal-looking number.**',['Apply formal criteria and clinical judgment carefully.','Treat important ketosis and the underlying trigger under supervision.'],[['Acidifying process','Ketoacid accumulation'],['Alkalinizing process','Vomiting/contraction'],['Assessment','Ketones plus full acid-base analysis']],[CR],'clinical_scenario')
q('A patient with diabetes and heavy alcohol use has high-gap ketoacidosis after poor intake. Which principle is most appropriate?', 'Consider overlapping diabetic, alcoholic and starvation mechanisms rather than assigning the cause from ketones alone',[
 ('Alcohol exposure rules out DKA','A person with diabetes can have overlapping mechanisms.'),('All ketosis requires identical insulin dosing regardless of glucose and cause','Treatment differs and hypoglycemia risk matters.'),('Urine ketones alone reliably distinguish the three','The assay does not determine the cause.')],
 'Ketosis is a mechanism shared by several clinical syndromes', '**Insulin deficiency, fasting and alcohol-related metabolic changes can overlap.**',['History, glucose, beta-hydroxybutyrate and acid-base findings guide interpretation.','Alcohol-related illness can include thiamine depletion and other electrolyte deficits.'], '**Treat immediate instability while clarifying the mechanism.**',['Provide thiamine and nutritional support when indicated.','Do not delay necessary DKA insulin or give it uncritically without glucose monitoring in other syndromes.'],[['DKA','Insulin deficiency'],['Starvation','Reduced intake'],['Alcoholic ketosis','Alcohol/poor-intake context']],[CR],'clinical_scenario')
